#define _CRT_SECURE_NO_WARNINGS
#define CDL2H

#include <stdint.h>
#include <limits.h>
#define VALUE long long
#define VALUE_MAX LLONG_MAX   
#define VALUE_MIN LLONG_MIN
#define VALUE_UNDEFINED VALUE_MIN
#define VALUE_FMT "ll"

#define VALUE_DEC_FORMAT "%" VALUE_FMT "d"
#define VALUE_UDEC_FORMAT "%" VALUE_FMT "u"
#define VALUE_HEX_FORMAT "%" VALUE_FMT "x"

#define VALUE_FMTC(n,b) "%0" #n VALUE_FMT b
#define VALUE_DEC_FMT(n) VALUE_FMTC(n,"d")
#define VALUE_HEX_FMT(n) VALUE_FMTC(n,"x")

// Format helper for string literal concatenation with VALUE format macros
#define FMT(s) s

//Add any necessary includes here.
#include <stdio.h>
