#ifdef WINDOWS
void debug_pause() {
    system("pause");
}
#else
// No equivalent of system("pause") on Linux and mac, so we just print a message and wait for user input.
void debug_pause() {
    printf("Press Enter to continue...");
    getchar();
}
#endif

void c2Abort(char* msg) {
   fprintf(stderr, "\x1b[31mABORT in %s\x1b[0m\\n", msg);
   exit(1);
}

// Define control constructs that have to be redefined when code with -trace is generated
#define ENTER(index,affixes,locals)
#define RETURNV(v) return v
#define RETURN return
#define ABORT(msg,index) c2Abort(msg)



// Define the some convenient types and macros for use in generated code.
//VALUE must already be defined.
#define BOOL VALUE
#define TRUE 1
#define FALSE 0
#define PREDICATE BOOL
#define TEST BOOL
#define ACTION void
#define FUNCTION void
#define PROC
#define MACRO

#define DECLARE_VAR(name) \
    VALUE name = VALUE_UNDEFINED

/* CDL2 Standard Macros for Lists */
#define DECLARE_LIST(name, lwb, upb) \
    VALUE name##_array[(upb) - (lwb) + 1]; \
    int name##_lwb = (int)(lwb); \
    int name##_upb = (int)(upb)

// Define a common bounds check macro
#define CDL2_BOUNDS_CHECK(name, i, action) \
    ((int)(i) >= name##_lwb && (int)(i) <= name##_upb) ? \
    true : \
    (fprintf(stderr, "%s: Index %d out of bounds in LIST %s(%d:%d)\n", action, (int)(i), #name, name##_lwb, name##_upb), exit(1), false)

#define CDL2_LIST_GET(name, i) \
    (CDL2_BOUNDS_CHECK(name, i, "GET") ? \
        name##_array[(int)(i) - name##_lwb] : VALUE_UNDEFINED)

#define CDL2_LIST_SET(name, i, value) \
    { \
        CDL2_BOUNDS_CHECK(name, i, "SET"); \
        name##_array[(int)(i) - name##_lwb] = (value); \
    }

#define CDL2_LIST_SWAP(name, i, j) \
    { \
        CDL2_BOUNDS_CHECK(name, i, "SWAP(...,i,...)"); \
        CDL2_BOUNDS_CHECK(name, j, "SWAP(...,...,j)"); \
        VALUE temp = name##_array[(int)(i) - name##_lwb]; \
        name##_array[(int)(i) - name##_lwb] = name##_array[(int)(j) - name##_lwb]; \
        name##_array[(int)(j) - name##_lwb] = temp; \
    }

    

